// Original practice content. Harbourland is a fictional economy; all data are illustrative.
import { M, F, A, tbl } from './helpers.js';
const c=(title,html)=>({title,html});
const mc=(q,options,answer,why,cmd='Identify')=>({type:'mcq',q,options,answer,why,cmd});
const tf=(q,answer,why)=>({type:'tf',q,answer,why});
const n=(q,answer,why,unit='')=>({type:'num',cmd:'Calculate',q,answer,why,unit,tol:0.01});
const lab=(title,buckets,items)=>({type:'sort',title,challenge:'Classify every case correctly.',buckets,items:items.map(([t,b])=>({t,b}))});
const w=(title,intro,steps,takeaway)=>({title,intro,steps:steps.map(([prompt,answer])=>({prompt,answer})),takeaway});
const tip='<div class="tip">Evaluate: follow the chain from policy to behaviour to the outcome, then judge a limitation in this context.</div>';
const HL='<span class="tag">HL</span> ';
const asDiagram='<svg viewBox="0 0 420 250" role="img" aria-label="Alternative aggregate supply curves: a vertical LRAS at potential output and a Keynesian curve that is flat at low output then steepens to full capacity" style="width:100%;height:auto;background:var(--card);color:var(--text);border-radius:12px"><path d="M45 18V205H395" fill="none" stroke="var(--text)" stroke-width="2"/><path d="M325 25V205" stroke="var(--chart-2)" stroke-width="3"/><path d="M58 173H180Q278 173 305 105Q325 70 325 30" fill="none" stroke="var(--chart-1)" stroke-width="3"/><text x="7" y="20" font-size="12" fill="var(--text)">Price level</text><text x="285" y="240" font-size="12" fill="var(--text)">Real output</text><text x="332" y="42" font-size="12" fill="var(--chart-2)">LRAS</text><text x="70" y="161" font-size="12" fill="var(--chart-1)">Keynesian AS</text><text x="302" y="222" font-size="12" fill="var(--text)">Y potential</text><text x="64" y="193" font-size="11" fill="var(--text)">Spare capacity</text></svg>';
const phillipsDiagram='<svg viewBox="0 0 420 250" role="img" aria-label="Short-run Phillips curve slopes down; long-run Phillips curve is vertical at the natural rate of unemployment" style="width:100%;height:auto;background:var(--card);color:var(--text);border-radius:12px"><path d="M45 18V205H395" fill="none" stroke="var(--text)" stroke-width="2"/><path d="M245 30V205" stroke="var(--chart-2)" stroke-width="3"/><path d="M80 40Q135 150 355 183" fill="none" stroke="var(--chart-1)" stroke-width="3"/><text x="5" y="17" font-size="12" fill="var(--text)">Inflation (%)</text><text x="242" y="240" font-size="12" fill="var(--text)">Unemployment (%)</text><text x="252" y="46" font-size="12" fill="var(--chart-2)">LRPC</text><text x="323" y="171" font-size="12" fill="var(--chart-1)">SRPC</text><text x="184" y="222" font-size="11" fill="var(--text)">Natural rate</text></svg>';
const sections=[
{
id:'3.1a',title:'National income: counting the economy',emoji:'🧮',minutes:14,hl:false,
goal:'calculate GDP, GNI, real income and income per person without double counting.',
hook:'<p>HarbourFest sells more tickets, but the imported speakers also cost more. A headline says Harbourland is richer because spending rose. You need to find out whether more output was actually produced and who receives the income.</p>',
cards:[
c('One flow, three ways to count it','<p><b>Gross domestic product (GDP)</b> is the value of final goods and services produced within an economy over a period. The output approach sums value added; the income approach sums income earned from production; the expenditure approach sums spending on final output. They measure the same flow in principle, although actual statistics have discrepancies.</p><div class="example">Count the festival’s final meal, or the value added at each stage. Adding the full wheat, flour and meal prices would double count intermediate production. Second-hand ticket transfers are not new production; a current booking service is.</div>'),
c('Spending on domestic output','<p><b>Consumption</b> is household spending on goods and services. <b>Investment</b> is spending on capital and additions to inventories. Government purchases count in G; transfers such as benefits do not directly buy current output. Exports add foreign spending on domestic output. Imports subtract foreign production already included in C, I or G.</p>'+F`GDP=C+I+G+(X-M)`+'<div class="example">An imported festival speaker belongs in investment, but imports remove its foreign-produced value. Purchasing shares transfers financial ownership; it is not itself new capital formation.</div>'),
c('Domestic production or residents’ income?','<p><b>Gross national income (GNI)</b> is residents’ income from production, including net primary income from abroad. Add income residents earn overseas and subtract income non-residents earn domestically.</p>'+F`GNI=GDP+\text{net primary income from abroad}`+'<div class="example">A foreign-owned hotel contributes to Harbourland GDP. Profits paid to its foreign owners reduce Harbourland GNI relative to GDP.</div>'),
c('Remove prices, then allow for population','<p><b>Nominal GDP</b> uses current prices. <b>Real GDP</b> removes changes in the price level, using a base-year price index. A <b>GDP deflator</b> measures prices of domestically produced final output. <b>Real GDP per capita</b> divides real GDP by population; apply the same method to real GNI.</p>'+F`\text{Real GDP}=\frac{\text{nominal GDP}}{\text{GDP deflator}}\times100`+F`\text{Real GDP per capita}=\frac{\text{real GDP}}{\text{population}}`+'<div class="example">Nominal GDP of 660 billion and a deflator of 110 give real GDP of 600 billion in base-year prices. With 10 million people, that is 60,000 per person.</div>'),
c('Check the accounting before judging','<p>State the currency, period, price basis and whether a figure is domestic, national or per person. A country can have rising real GDP but falling real GDP per capita if population rises faster. Statistical estimates omit or imperfectly measure some informal and unpaid production.</p><div class="tip">Calculate: show the formula, substitution and units. Never add transfers to G or subtract imports twice.</div>')],
labs:[lab('Harbourland’s national accountant',['Included directly in GDP expenditure','Excluded directly'],[['A household buys a newly made domestic bicycle',0],['Government buys a current nursing service',0],['A cash unemployment benefit is paid',1],['A saver buys existing company shares',1],['A firm adds unsold new goods to inventories',0],['A family sells its old sofa privately',1]])],
worked:w('Follow spending through the accounts',tbl(['Item','Billion H$'],[['C','400'],['I','100'],['G','120'],['X','80'],['M','100'],['Net primary income from abroad','−20'],['GDP deflator','120']]),[['What is nominal GDP?','400 + 100 + 120 + 80 − 100 = H$600 billion.'],['What is nominal GNI?','600 − 20 = H$580 billion: residents receive less net income than is produced domestically.'],['What is real GDP?','600 / 120 × 100 = H$500 billion at base-year prices.'],['How should you report it?','Keep GDP and GNI separate and state the price basis; H$500 billion is real GDP, not nominal GNI.']],'An accounting identity is a way to measure a flow, not proof that every extra dollar improves welfare.'),
quiz:[mc('GDP measures production primarily by…',['Location within the economy','Nationality of all shareholders','Residents’ worldwide income only','Household wealth at one date'],0,'GDP follows domestic production over a period.'),tf('Buying an existing share is counted as new investment in the GDP expenditure formula.',false,'Financial transactions do not themselves create new capital goods.'),n('Calculate nominal GDP.'+tbl(['Item','Billion H$'],[['C','300'],['I','80'],['G','90'],['X','60'],['M','70'],['GDP',A(460,true)]]),460,'300 + 80 + 90 + 60 − 70 = 460.','billion H$'),n('Calculate GNI.'+tbl(['Item','Billion H$'],[['GDP','460'],['Primary income received abroad','30'],['Primary income paid abroad','50'],['GNI',A(440,true)]]),440,'460 + 30 − 50 = 440.','billion H$'),n('Calculate real GDP.'+tbl(['Item','Value'],[['Nominal GDP (billion H$)','660'],['Deflator (base = 100)','110'],['Real GDP (billion H$)',A(600,true)]]),600,'660 / 110 × 100 = 600.','billion H$'),n('Calculate real GDP per capita.'+tbl(['Item','Value'],[['Real GDP (billion H$)','600'],['Population (million)','10'],['Real GDP per person (H$)',A(60000,true)]]),60000,'600 billion / 10 million = H$60,000.','H$'),mc('Why subtract imports in GDP expenditure?',['They are foreign output already included in spending categories','All imports lower well-being','Exports already include every import','Imports are transfer payments'],0,'Subtracting imports isolates domestic production.'),tf('Output, income and expenditure approaches should measure the same economic flow in principle.',true,'Spending on output becomes income; output value added avoids double counting.')],
explain:'Text a friend why a foreign-owned hotel can raise Harbourland GDP by more than its GNI.'
},
{
id:'3.1b',title:'Business cycles and living standards',emoji:'🎢',minutes:12,hl:false,
goal:'interpret business cycles and evaluate income statistics as measures of well-being.',
hook:'<p>Last summer every HarbourFest stall was hiring. This year families cut spending and your friend cannot find a shift. GDP per person still looks high, so what does the headline miss?</p>',
cards:[c('Actual output fluctuates','<p>The <b>business cycle</b> describes fluctuations in real economic activity around its longer-term trend. Expansion raises actual output; a peak precedes contraction, and a trough precedes recovery. A recession is a period of declining economic activity; two consecutive quarters of falling real GDP is a commonly used rule of thumb, not a universal definition.</p><div class="example">During contraction, festival suppliers sell less and reduce hiring. Potential output need not fall at the same time.</div>'),c('Capacity and gaps','<p><b>Potential output</b> is the output sustainable when resources are normally and fully employed, allowing for normal unemployment. A <b>negative output gap</b> means actual output is below potential; a positive gap means output temporarily exceeds sustainable capacity.</p><p>Draw real GDP on the vertical axis and time on the horizontal axis. Add a rising potential trend and an actual-output cycle; label peak, trough and gaps.</p><div class="example">Producing 95 when sustainable capacity is 100 indicates spare capacity. A rising actual line can still be below potential.</div>'),c('Compare like with like','<p>Use real figures for changes over time and per-person figures when population differs. <b>Purchasing power parity (PPP)</b> adjusts currency comparisons for different price levels: the same income buys different baskets across countries.</p><div class="example">A higher converted salary abroad may buy fewer meals if local prices are much higher. PPP helps compare material purchasing power, but national averages still hide distribution.</div>'),c('Averages leave people out','<p>GDP per capita says little directly about inequality, unpaid care, leisure, health, environmental damage or whether output is sustainable. Defensive spending after a flood can raise GDP while people are worse off. Informal activity and data quality complicate comparisons.</p><div class="example">Harbourland’s output rises because of expensive flood repairs. That does not mean households prefer the flood to an undamaged home.</div>'),c('Use a dashboard','<p>The <b>OECD Better Life Index</b> considers several dimensions of living conditions; happiness measures use reported life evaluations; the <b>Happy Planet Index</b> relates well-being to environmental resource use. These complement income figures but depend on choices about measurement, weighting and comparability.</p><div class="tip">Evaluate: select indicators for the question. For household material purchasing power use real income per capita at PPP, then add distribution, health and sustainability evidence.</div>')],
labs:[lab('Read the business cycle',['Expansion','Contraction','Potential capacity change'],[['Real output rises as idle workers return',0],['Sales and real output fall for several months',1],['New technology increases sustainable production',2],['A recovery raises hiring from a trough',0],['A disaster permanently destroys productive equipment',2],['Consumers cut spending and firms reduce output',1]])],
worked:w('Is Harbourland better off?',tbl(['Indicator','Year A','Year B'],[['Real GDP (billion H$)','500','510'],['Population (million)','10','10.5'],['River water quality','Good','Poor']]),[['Has total production risen?','Yes: real GDP rises by 2%.'],['Has output per person risen?','No. It falls from 50,000 to about H$48,571.43 because population grows faster than output.'],['What does the river evidence add?','Environmental quality has deteriorated; GDP does not directly deduct this loss of well-being.'],['What judgement is justified?','The evidence does not support a general claim that everyone is better off. Add distribution and health indicators.']],'Use both appropriate income measures and non-income evidence.'),
quiz:[mc('The business cycle primarily tracks…',['Fluctuations in real activity over time','Daily movements in one share price','Only changes in population','The age of one company'],0,'The business cycle concerns economy-wide real activity.'),mc('Actual output below potential indicates…',['A negative output gap','A positive output gap','No possible spare capacity','A necessarily falling potential trend'],0,'Actual output is lower than sustainable capacity.'),tf('An expansion must put actual output above potential.',false,'Output can rise during recovery while remaining below potential.'),mc('For material living standards across countries, which starting measure is strongest?',['Real income per capita at PPP','Total nominal GDP alone','Population alone','One currency’s face value'],0,'It adjusts for prices, population and purchasing power, while still needing qualifications.'),n('Calculate real GDP per person.'+tbl(['Item','Value'],[['Real GDP (billion H$)','520'],['Population (million)','10'],['Per capita output (H$)',A(52000,true)]]),52000,'520 billion / 10 million = 52,000.','H$'),tf('Unpaid family care is fully captured in measured GDP.',false,'Much unpaid household activity is outside standard GDP measurement.'),mc('Which best challenges “higher GDP always means higher well-being”?',['Pollution damage rises alongside measured production','Output and expenditure are related','A final good is counted once','Prices can be indexed'],0,'GDP can rise alongside environmental harm and other welfare losses.'),mc('Why use several well-being indicators?',['Different measures capture different dimensions and value judgements','Every indicator measures exactly the same thing','It eliminates all judgement','It makes national statistics unnecessary'],0,'A dashboard reveals dimensions hidden by a single average.')],explain:'Text a friend why a country can get a bigger GDP headline while your own life gets harder.'
},
{
id:'3.2',title:'Aggregate demand and aggregate supply',emoji:'📊',minutes:15,hl:'part',
goal:'explain macroeconomic equilibrium, shocks and different views of adjustment.',
hook:'<p>HarbourFest’s cafes are quiet even though food is cheap to make. Months later imported energy becomes expensive and the same cafes raise prices while cutting hours. These two slowdowns need different explanations.</p>',
cards:[c('Spending across the economy','<p><b>Aggregate demand (AD)</b> is total planned spending on domestic output at each average price level. It includes C, I, G and net exports. Its downward slope reflects purchasing-power, interest-rate and international competitiveness effects, rather than a movement in one product’s price.</p><div class="example">Higher confidence, wealth or government purchases can shift AD right. Higher household debt burdens can reduce consumption; weak expected sales can reduce investment.</div>'+F`AD=C+I+G+(X-M)`),c('Supply now','<p><b>Short-run aggregate supply (SRAS)</b> relates planned output to the average price level when some input prices are sticky. Its upward slope reflects rising costs as output expands. Higher energy prices or wages unrelated to productivity shift SRAS left; lower unit costs shift it right.</p><div class="example">An oil-price rise makes the festival’s deliveries more costly. Output falls and the price level rises: a supply shock.</div>'),c('Two views of the longer run','<p>The <b>new classical LRAS</b> curve is vertical at potential output. Flexible wages and prices are expected to return output to this level in the long run. <b>Keynesian aggregate supply</b> is relatively flat when spare capacity is large, rises as bottlenecks appear and becomes vertical at full capacity.</p><div class="example">Extra festival spending can mainly raise output when workers are idle, but mainly raise prices when venues and staff are fully used. The models imply different speeds and costs of self-correction.</div>'),c('Equilibrium and policy','<p>Macroeconomic equilibrium occurs where AD intersects the relevant AS curve. Put average price level vertically and real output horizontally. A demand increase raises output and prices along SRAS; the relative changes depend on spare capacity. Education, technology and infrastructure can increase potential output, shifting LRAS or Keynesian AS right.</p><div class="tip">Analyse: label initial and new equilibria, identify the curve that shifts and explain why. A change in the average price level causes a movement along AD, not a shift of AD.</div>'),c('HL: repeated rounds of spending',HL+'<p>The <b>multiplier</b> is the change in equilibrium income divided by an initial change in autonomous spending. The <b>marginal propensity to consume (MPC)</b> is the fraction of extra income consumed; marginal propensities to save, tax and import are leakages.</p>'+F`k=\frac{1}{MPS+MPT+MPM}`+F`\Delta Y=k\times\Delta J`+'<div class="example">If marginal leakages total 0.4, k = 2.5. An autonomous H$20 million injection can raise equilibrium income by H$50 million in a simple model with spare capacity, fixed price level and unchanged propensities. At capacity, inflation and crowding out weaken the real effect.</div>')],
labs:[lab('Identify the shock',['AD shifts right','AD shifts left','SRAS shifts left','Potential AS shifts right'],[['Households become more confident',0],['Government cuts current purchases',1],['Imported energy becomes more expensive',2],['Training raises workforce productivity',3],['Foreign incomes rise and buy more exports',0],['A banking crisis cuts lending and investment',1]])],
worked:w('Energy shock at HarbourFest','<p>Imported fuel becomes more expensive while domestic spending intentions initially stay unchanged.</p>',[['Which curve shifts?','SRAS shifts left because production costs rise at each price level.'],['What happens to equilibrium?','Along unchanged AD, the new equilibrium has a higher price level and lower real output.'],['Why is policy difficult?','Boosting AD may recover output but raise prices further. Reducing AD tackles price pressure but can deepen unemployment.'],['What else could help?','Energy efficiency and diversified supply may reduce costs over time; they take investment and may not solve the immediate shock.']],'Diagnose the source of the shock before choosing a demand response.'),
quiz:[mc('A rise in consumer confidence mainly shifts…',['AD right','AD left','SRAS left automatically','LRAS left automatically'],0,'Higher intended consumption raises aggregate demand at each price level.'),mc('A rise in imported fuel costs initially causes…',['Higher price level and lower output','Lower price level and higher output','Only an AD shift right','A guaranteed increase in potential output'],0,'A leftward SRAS shift creates cost-push pressure and reduces output.'),tf('The average price level rising by itself shifts AD left.',false,'It causes movement along an unchanged AD curve.'),mc('A vertical new classical LRAS represents…',['Potential output independent of the price level','Unlimited spare capacity','A demand curve for labour','Permanent excess demand at every price'],0,'In this model long-run output depends on real productive resources.'),mc('In a relatively flat Keynesian AS region, higher AD mainly raises…',['Real output','Only the price level','Unemployment','Imports with no domestic effect'],0,'Spare capacity permits more output with relatively little price pressure.'),n(HL+'Calculate the multiplier.'+tbl(['Marginal leakage','Value'],[['MPS','0.20'],['MPT','0.10'],['MPM','0.10'],['Multiplier',A(2.5,true)]]),2.5,'1 / (0.20 + 0.10 + 0.10) = 2.5.'),n(HL+'Calculate the model’s income change.'+tbl(['Item','Value'],[['Autonomous injection (million H$)','20'],['Multiplier','2.5'],['Income change (million H$)',A(50,true)]]),50,'2.5 × 20 = H$50 million, assuming spare capacity and the simple model’s conditions.','million H$'),tf('An increase in productive capacity necessarily raises actual output immediately.',false,'Capacity can expand while weak demand leaves resources unemployed.')],explain:'Text a friend why a fuel-price shock and a confidence crash require different policy judgements.'
},
{
id:'3.3a',title:'Growth and unemployment',emoji:'🧑‍💼',minutes:14,hl:false,
goal:'measure growth and unemployment and distinguish their causes and consequences.',
hook:'<p>Your friend loses a HarbourFest shift when tourism falls. Another cannot use the booking system employers now require. Both are unemployed, but would one extra government concert solve both problems?</p>',
cards:[c('More output or more capacity?','<p><b>Economic growth</b> is an increase in real GDP over time. Actual growth can use idle resources; potential growth expands productive capacity. Investment, education, technology and institutional improvements can raise capacity.</p>'+F`\text{Growth rate}=\frac{Y_1-Y_0}{Y_0}\times100`+'<div class="example">Real GDP rising from 500 to 520 is 4% growth. Growth can fund services and jobs, but benefits depend on distribution, environmental costs and what is produced.</div>'),c('Who counts as unemployed?','<p><b>Unemployment</b> refers to people without work who are available for work and actively seeking it. The <b>labour force</b> includes employed plus unemployed people. Students not seeking work are outside the labour force; part-time workers are employed even if they want more hours.</p>'+F`u=\frac{\text{unemployed}}{\text{labour force}}\times100`+'<div class="example">Discouraged workers who stop searching may disappear from the measured unemployment rate without finding jobs. Underemployment means workers’ available time or skills are not fully used.</div>'),c('Different causes, different remedies','<p><b>Frictional unemployment</b> occurs during job search between suitable jobs. <b>Structural unemployment</b> arises from mismatches of skills or location as production changes. <b>Seasonal unemployment</b> follows recurring seasonal demand. <b>Cyclical unemployment</b> follows insufficient aggregate demand during downturns.</p><div class="example">Waiting for another summer festival is seasonal. Losing demand during a national recession is cyclical. Lacking digital skills after automation is structural.</div>'),c('Full employment is not zero unemployment','<p>The <b>natural rate of unemployment</b> is the unemployment consistent with an economy at potential output, including frictional and structural components. It can change with institutions, skills and mobility. A recession adds cyclical unemployment.</p><p>On a labour-market diagram, wage rigidity above the clearing wage can leave labour supplied greater than labour demanded. In an AD/AS diagram, deficient demand leaves output below potential. These are explanations to assess, not interchangeable claims.</p>'),c('Human costs and policy choices','<p>Unemployment reduces income and tax revenue, raises some benefit spending and can damage health, skills and social inclusion. Demand stimulus can reduce cyclical unemployment; retraining, better job information, mobility support and childcare can tackle mismatches. Policies face costs and time lags.</p>'+tip)],
labs:[lab('Find the cause',['Frictional','Structural','Seasonal','Cyclical'],[['A graduate searches for a first suitable job',0],['An automated venue no longer needs manual scanners',1],['Outdoor festival staff lose work each winter',2],['A recession reduces orders throughout the economy',3],['A worker moves between two suitable jobs',0],['Available jobs are far from workers with immobile housing',1]])],
worked:w('Read the jobs headline',tbl(['Harbourland labour market','Million people'],[['Employed','4.5'],['Unemployed and seeking work','0.5'],['Outside labour force','2']]),[['What is the labour force?','4.5 + 0.5 = 5 million. Do not include the 2 million outside it.'],['What is unemployment?','0.5 / 5 × 100 = 10%.'],['What if 0.1 million unemployed people stop searching?','Measured unemployed fall to 0.4 million and the labour force falls to 4.9 million. The rate becomes about 8.16%, even though employment is unchanged.'],['What evidence would improve the judgement?','Check participation, hours worked, underemployment and job quality alongside the unemployment rate.']],'A falling unemployment rate does not by itself prove that more people have jobs.'),
quiz:[n('Calculate real GDP growth.'+tbl(['Item','Billion H$'],[['Initial real GDP','500'],['Final real GDP','520'],['Growth (%)',A(4,true)]]),4,'(520 − 500) / 500 × 100 = 4%.','%'),n('Calculate unemployment.'+tbl(['Item','Million people'],[['Employed','4.5'],['Unemployed','0.5'],['Labour force',A(5)],['Unemployment rate (%)',A(10,true)]]),10,'Labour force = 5 million; 0.5 / 5 × 100 = 10%.','%'),mc('Automation leaves workers without the skills required by vacancies. This is mainly…',['Structural unemployment','Frictional unemployment only','Seasonal unemployment only','An increase in labour productivity with no unemployment risk'],0,'The available skills and job requirements no longer match.'),mc('A nationwide spending collapse mainly raises…',['Cyclical unemployment','Only seasonal unemployment','Only frictional unemployment','Potential output automatically'],0,'Lower aggregate demand reduces derived demand for labour.'),tf('Full employment requires every person to have a paid job.',false,'It allows normal unemployment and excludes people outside the labour force.'),mc('Which policy most directly addresses a skill mismatch?',['Relevant retraining linked to vacancies','A general sales campaign alone','Counting students as unemployed','Reducing published statistics'],0,'Retraining can improve employability for the jobs available.'),tf('A lower unemployment rate always means employment has risen.',false,'Discouraged workers leaving the labour force can lower the measured rate.'),mc('Which qualifies a growth judgement?',['Who receives the gains and what environmental costs arise','Whether nominal GDP alone rose','Whether every price is unchanged forever','Whether leisure is completely excluded from people’s goals'],0,'The distribution and sustainability of growth influence well-being.')],explain:'Text a friend why a training course may fix structural unemployment better than a one-off spending boost.'
},
{
id:'3.3b',title:'Inflation, deflation and policy trade-offs',emoji:'🔥',minutes:14,hl:'part',
goal:'calculate inflation, explain its causes and assess conflicts between macroeconomic objectives.',
hook:'<p>Your festival wage rises, but meals and bus fares rise faster. Later the inflation headline falls while your lunch still gets more expensive. You want to know whether prices, price changes or purchasing power have improved.</p>',
cards:[c('Price level versus its rate of change','<p><b>Inflation</b> is a sustained increase in the general price level. <b>Disinflation</b> means inflation slows while prices still rise. <b>Deflation</b> is a sustained fall in the general price level. One expensive concert is a relative price change, not evidence on its own of general inflation.</p>'+F`\pi=\frac{CPI_1-CPI_0}{CPI_0}\times100`+'<div class="example">A CPI rising from 120 to 126 means 5% inflation. If inflation later falls to 2%, the general price level continues rising more slowly.</div>'),c('A basket with weights','<p>A <b>consumer price index (CPI)</b> tracks the cost of a representative basket of consumer goods and services relative to a base period. Expenditure weights reflect the importance of different categories. Different households experience different inflation; basket choice, substitution, quality change and new products complicate measurement.</p>'+F`CPI=\frac{\text{basket cost now}}{\text{basket cost in base year}}\times100`+'<div class="example">A student spending heavily on rent may face a different cost increase from the average basket. The GDP deflator covers domestic output rather than the consumer basket.</div>'),c('Demand-pull and cost-push','<p><b>Demand-pull inflation</b> arises when AD grows strongly relative to productive capacity. <b>Cost-push inflation</b> arises from rising production costs and leftward SRAS shifts. Expectations can influence wage and price setting and prolong inflation.</p><div class="example">A spending surge at full capacity puts upward pressure on prices. A fuel shortage raises prices while cutting output. The source matters for policy.</div>'),c('Who wins, who loses?','<p>Unexpected inflation redistributes between creditors and debtors, erodes fixed nominal incomes, creates uncertainty and can damage external competitiveness. Outcomes depend on indexation and whether inflation is expected. Deflation can raise real debt burdens and encourage delayed spending, weakening AD; productivity-driven price falls can have different effects.</p><div class="example">A fixed-rate borrower repays in money with less purchasing power after unexpected inflation, while the lender loses. This does not mean every borrower benefits after interest rates adjust.</div>'),c('HL: the Phillips curve and conflicts',HL+'<p>A <b>short-run Phillips curve</b> describes a possible inverse relationship between unemployment and inflation for given expectations and supply conditions. Stronger AD can reduce cyclical unemployment while increasing inflation. Adverse supply shocks can raise both, shifting the relationship.</p><p>The <b>long-run Phillips curve</b> is vertical at the natural rate in the expectations-augmented model: there is no permanent inflation–unemployment trade-off. Attempting to hold unemployment below that rate can lead to accelerating inflation as expectations adjust. Growth, equity, low inflation, employment and environmental objectives may conflict; supply improvements can ease some conflicts.</p>'+tip)],
labs:[lab('Decode the price news',['Inflation','Disinflation','Deflation','Relative price only'],[['The general price level rises 4%',0],['Inflation slows from 6% to 3%',1],['The general price level falls 2%',2],['Only one concert doubles its ticket price',3],['All-basket prices rise more slowly than last year',1],['The price level falls for a sustained period',2]])],
worked:w('Is your festival wage keeping up?',tbl(['Indicator','Initial','Final'],[['Nominal hourly wage (H$)','100','103'],['CPI','100','105']]),[['What is wage growth?','(103 − 100) / 100 × 100 = 3%.'],['What is inflation?','(105 − 100) / 100 × 100 = 5%.'],['What happens to real purchasing power?','The final real wage in initial prices is 103 / 105 × 100 = H$98.10 approximately, below H$100. The exact real wage decline is about 1.90%.'],['What if next year inflation is only 2%?','Prices still rise; whether your real wage recovers depends on next year’s nominal wage growth.']],'A lower inflation rate is not the same as a lower price level.'),
quiz:[n('Calculate inflation.'+tbl(['Item','Index'],[['Initial CPI','120'],['Final CPI','126'],['Inflation (%)',A(5,true)]]),5,'(126 − 120) / 120 × 100 = 5%.','%'),n('Calculate CPI.'+tbl(['Basket cost','H$'],[['Base year','200'],['Current year','230'],['CPI',A(115,true)]]),115,'230 / 200 × 100 = 115.'),mc('Inflation slows from 7% to 3%. This is…',['Disinflation','Deflation','A fall in all prices to their base values','No rise in the price level'],0,'Prices continue to rise, at a slower rate.'),mc('Imported energy costs surge. Which is the likely initial effect?',['Cost-push inflation and lower output','Demand-pull inflation only','Lower prices and higher output','A guaranteed fall in unemployment'],0,'SRAS shifts left, producing an inflation/output trade-off.'),tf('Unexpected inflation can reduce the real burden of a fixed nominal debt.',true,'Repayment has lower purchasing power, although contractual and interest-rate conditions matter.'),mc('Why can deflation deepen a demand recession?',['Real debt burdens rise and some spending is delayed','Every wage must immediately double','Real interest rates must be negative','Imports cease to exist'],0,'Falling prices can make fixed debts harder to service and weaken demand.'),mc(HL+'The long-run Phillips curve is vertical in the expectations-augmented model because…',['Expectations adjust; there is no permanent demand-driven trade-off','Inflation is always zero','Unemployment cannot change in the short run','Supply shocks are impossible'],0,'Attempts to sustain output above potential raise inflation expectations.'),tf(HL+'An adverse supply shock can raise both inflation and unemployment.',true,'Lower output reduces labour demand while higher costs raise the price level.')],explain:'Text a friend why inflation falling to 2% does not mean the festival meal price will go back down.'
},
{
id:'3.4',title:'Inequality, poverty and redistribution',emoji:'⚖️',minutes:14,hl:'part',
goal:'interpret inequality measures, distinguish poverty concepts and calculate tax effects.',
hook:'<p>Harbourland’s average income rises, but your friend still cannot afford the bus to work. Two families earn the same gross pay yet face different needs and taxes. How should the government judge fairness and choose support?</p>',
cards:[c('Income is a flow; wealth is a stock','<p><b>Income inequality</b> is uneven distribution of income over a period. <b>Wealth inequality</b> concerns uneven ownership of assets net of liabilities at a point in time. Inherited assets, education, bargaining power, discrimination and differing opportunities can reinforce unequal outcomes.</p><div class="example">Two students earn the same part-time wage; one inherits an apartment and the other pays rent. Equal wages do not imply equal wealth or living conditions.</div>'),c('Read a Lorenz curve','<p>A <b>Lorenz curve</b> plots cumulative population shares from poorest to richest horizontally and cumulative income shares vertically. The diagonal represents complete equality. A curve further below it generally indicates greater inequality, though crossing curves complicate comparisons.</p><p>The <b>Gini coefficient</b> is the area between the equality line and Lorenz curve divided by the whole area below the equality line. Zero represents complete equality; a value approaching one indicates extreme inequality. It can also be reported on a 0–100 scale.</p>'+F`G=\frac{A}{A+B}`),c('Poverty is more than one number','<p><b>Absolute poverty</b> means inability to meet a defined basic-needs standard. <b>Relative poverty</b> means having income or resources far below the typical standard in a society, often measured against a fraction of median income. <b>Multidimensional poverty</b> also considers deprivations such as schooling, health and living conditions.</p><div class="example">Growth can reduce absolute deprivation while relative poverty persists if the median rises faster than low incomes. Poverty can harm health and schooling, limiting future earning capacity.</div>'),c('Taxes, transfers and services','<p>A <b>progressive tax</b> takes a higher average share as income rises; a proportional tax takes a constant share; a regressive tax takes a lower average share. Cash transfers, public education, healthcare, targeted benefits and minimum wages can influence distribution, each with eligibility, incentive, financing and enforcement issues.</p><div class="example">A consumption tax may be regressive relative to income if poorer households spend a larger income share. Targeted compensation can offset some impact.</div>'+tip),c('HL: marginal is not average',HL+'<p>The <b>marginal tax rate</b> applies to additional income; the <b>average tax rate</b> is total tax divided by total income. In a band system, a higher rate normally applies only to income inside that band.</p>'+F`ATR=\frac{\text{total tax}}{\text{income}}\times100`+F`MTR=\frac{\Delta\text{tax}}{\Delta\text{income}}\times100`+'<div class="example">First H$10,000 untaxed, next H$20,000 taxed at 20%, excess at 40%: on H$40,000 income, tax is 0 + 4,000 + 4,000 = H$8,000. Average rate is 20%; marginal rate is 40%.</div>')],
labs:[lab('Match the measure',['Income','Wealth','Absolute poverty','Relative poverty'],[['Annual wages from festival work',0],['A home’s value minus its mortgage',1],['Resources insufficient for basic nutrition',2],['Income below a stated fraction of the national median',3],['Annual rental earnings',0],['Net accumulated savings and owned assets',1]])],
worked:w('Tax one band at a time',HL+tbl(['Annual income band (H$)','Rate'],[['First 10,000','0%'],['Next 20,000','20%'],['Above 30,000','40%'],['Person’s income','40,000']]),[['What tax falls on the first band?','10,000 × 0 = H$0.'],['What tax falls on the next two bands?','20,000 × 0.20 = H$4,000; the remaining 10,000 × 0.40 = H$4,000.'],['What are total tax and disposable income?','Tax = H$8,000. Income after this tax = H$32,000, assuming no other taxes or transfers.'],['What are the average and marginal rates?','Average = 8,000 / 40,000 × 100 = 20%. Marginal = 40% on the next dollar in the top band.']],'Do not apply the highest marginal rate to the whole income.'),
quiz:[mc('Which is wealth?',['Net value of owned property and financial assets','A month’s wage payment','Annual interest income','A year’s rental earnings'],0,'Wealth is a stock measured at a point in time.'),mc('A Lorenz curve plots cumulative income against…',['Cumulative population ordered poorest to richest','Time in months','Inflation rates','Marginal tax bands'],0,'Ordering by income shows how total income is distributed across people.'),tf('A Gini coefficient of zero represents complete equality.',true,'There is no area between the Lorenz curve and equality line.'),mc('Absolute poverty concerns…',['Inability to meet a defined basic-needs standard','Income below every other person’s income','Any unequal wealth distribution','Only dissatisfaction with a luxury purchase'],0,'Absolute poverty is assessed against basic needs, rather than only relative position.'),n(HL+'Calculate total income tax.'+tbl(['Band (H$)','Tax rate'],[['First 10,000','0%'],['Next 20,000','20%'],['Above 30,000','40%'],['Income','40,000'],['Total tax (H$)',A(8000,true)]]),8000,'0 + 20,000 × 0.2 + 10,000 × 0.4 = 8,000.','H$'),n(HL+'Calculate the average tax rate.'+tbl(['Item','H$'],[['Total tax','8,000'],['Income','40,000'],['Average rate (%)',A(20,true)]]),20,'8,000 / 40,000 × 100 = 20%.','%'),mc('Which is a limitation of targeted benefits?',['Eligible people may fail to claim, and administration costs resources','They can never improve income','They eliminate all incentive effects','They require no information'],0,'Targeting depends on information and access, and can create withdrawal-rate incentives.'),tf('Real GDP per capita growth guarantees that relative poverty falls.',false,'Low incomes may grow more slowly than the median, and gains may be unevenly distributed.')],explain:'Text a friend why entering a 40% tax band does not mean losing 40% of all your pay.'
},
{
id:'3.5',title:'Monetary policy: interest rates and demand',emoji:'🏦',minutes:14,hl:'part',
goal:'explain monetary transmission and evaluate its strengths and limitations.',
hook:'<p>Harbourland’s central bank raises its policy interest rate. Your household’s loan payment may rise and the festival’s equipment loan becomes less attractive. How can one decision affect spending, jobs and prices across the country?</p>',
cards:[c('The central bank’s tools','<p><b>Monetary policy</b> uses interest rates and monetary conditions to influence macroeconomic objectives. A central bank commonly sets a short-term policy rate, acts as banker to banks and government, manages reserves and supports financial stability. Its precise responsibilities differ across economies.</p><p>A restrictive policy raises rates or tightens monetary conditions to restrain demand; an expansionary policy lowers rates or eases conditions. An <b>inflation target</b> provides an announced objective that may help anchor expectations.</p>'),c('From rate to spending','<p>Higher interest rates can raise borrowing costs, encourage saving and reduce consumption and investment. Existing variable-rate borrowers may have less disposable income. Changes in asset prices and confidence can reinforce or weaken these effects. Lower AD then reduces demand-pull inflation pressure, with time lags.</p><div class="example">HarbourFest delays a new stage because expected ticket income no longer covers more expensive finance. Savers receiving extra interest may increase spending, partly offsetting borrowers’ cuts.</div>'),c('The exchange-rate channel','<p>Higher relative interest rates may attract financial inflows and appreciate the currency, other influences held constant. Cheaper imports can lower imported inflation, while more expensive exports and cheaper imports can reduce net exports and AD. Expectations and risk mean the exchange-rate response is not automatic.</p><div class="example">Foreign lighting equipment becomes cheaper in Harbourland currency after appreciation, but tourists may find the festival more expensive.</div>'),c('HL: money markets and unconventional policy',HL+'<p>In a simple money-market diagram, put the interest rate vertically and quantity of money horizontally. Money demand slopes down; a rightward money-supply shift lowers the equilibrium rate, other things equal. Modern rate-setting systems may implement policy differently from this simplified model.</p><p><b>Quantitative easing (QE)</b> involves central-bank purchases of financial assets, intended to reduce longer-term yields and support credit, spending and expectations. Near very low rates, weak confidence, debt and banks’ reluctance to lend can weaken transmission. More reserves do not guarantee more productive loans.</p>'),c('Evaluate effectiveness','<p>Monetary policy can change relatively quickly, but spending and inflation respond with uncertain lags. Restriction can curb excess demand while worsening unemployment. It is less suited to directly repairing a fuel shortage or skills gap. Central-bank credibility, independence, financial conditions and the source of inflation shape the result.</p>'+tip)],
labs:[lab('Trace the transmission',['Likely contractionary channel','Likely expansionary channel','Limitation or uncertainty'],[['Higher loan rates discourage equipment investment',0],['Lower mortgage payments release income for spending',1],['Banks refuse new loans despite lower policy rates',2],['Higher relative rates may reduce net exports through appreciation',0],['Weak confidence prevents firms borrowing even at low rates',2],['Lower borrowing costs encourage some household purchases',1]])],
worked:w('Should Harbourland raise rates?','<p>Inflation is rising after a boom in household spending, and output is above estimated potential.</p>',[['What is the diagnosis?','Demand-pull pressure: AD is high relative to productive capacity.'],['How might a rate rise work?','More expensive borrowing and stronger saving incentives reduce C and I; appreciation may reduce net exports. AD growth slows.'],['What are the likely costs?','Output and employment may fall; indebted households are hit unevenly. Results take time and estimates of potential are uncertain.'],['What judgement follows?','Restriction has a plausible case if excess demand persists, but its size should consider lags, debt exposure and incoming evidence.']],'A policy judgement needs a diagnosis, transmission chain and context-based limitation.'),
quiz:[mc('An expansionary monetary policy usually begins with…',['Lower policy interest rates','Higher income tax rates','A permanent ban on imports','Lower education spending'],0,'Lower borrowing costs are intended to stimulate demand.'),mc('Higher borrowing costs most directly tend to…',['Reduce interest-sensitive consumption and investment','Shift LRAS right immediately','Eliminate structural unemployment','Guarantee currency depreciation'],0,'Some purchases and investment become less attractive or affordable.'),tf('A policy-rate cut guarantees that banks lend and firms invest.',false,'Credit risks, confidence and expected profitability can interrupt transmission.'),mc('Higher relative interest rates may reduce imported inflation through…',['Currency appreciation','Currency depreciation necessarily','A direct rise in import tariffs','Lower labour productivity'],0,'Appreciation lowers local-currency import prices, other things equal.'),n('Calculate annual interest under a simple one-year loan assumption.'+tbl(['Item','Value'],[['Loan (H$)','20,000'],['Annual interest rate','5%'],['Interest (H$)',A(1000,true)]]),1000,'20,000 × 0.05 = H$1,000; this assumes simple interest with no principal repayment during the year.','H$'),mc(HL+'Quantitative easing involves…',['Central-bank purchases of financial assets','Government directly cutting every wage','Households buying only imports','A guaranteed equal transfer to every household'],0,'Asset purchases seek to ease financial conditions, including longer-term yields.'),tf('A rate rise can reduce demand-pull inflation while increasing unemployment.',true,'Lower AD can reduce output and derived demand for labour.'),mc('Which most limits monetary policy against an energy shortage?',['It does not directly restore energy supply','It cannot influence any spending','It always increases productive capacity instantly','It removes the need for fiscal decisions'],0,'Demand restraint can limit second-round pressure but cannot itself repair supply.')],explain:'Text a friend how a policy-rate rise might affect both the festival’s loan and your household budget.'
},
{
id:'3.6',title:'Fiscal policy: budgets and multipliers',emoji:'🧾',minutes:14,hl:'part',
goal:'explain fiscal stabilisation, calculate budget balances and evaluate multiplier effects.',
hook:'<p>Harbourland’s government proposes better buses and a temporary tax cut during a downturn. Opponents worry about borrowing and inflation. You need to distinguish a useful boost to demand from spending that arrives too late.</p>',
cards:[c('Government spending and taxation','<p><b>Fiscal policy</b> changes government spending and taxation to influence macroeconomic objectives. Expansionary policy raises spending or lowers taxes to stimulate AD; contractionary policy does the reverse. Purchases enter G directly, whereas tax and transfer changes affect disposable income and consumption.</p><div class="example">A public bus purchase raises G. A benefit payment is not itself G, but recipients may spend part of it, increasing C.</div>'),c('Deficit, surplus and debt','<p>A <b>budget deficit</b> occurs when government expenditure exceeds revenue over a period. A <b>budget surplus</b> is the reverse. <b>Public debt</b> is the outstanding stock of government borrowing, affected by past borrowing and other adjustments.</p>'+F`\text{Budget balance}=\text{revenue}-\text{expenditure}`+'<div class="example">Revenue of H$90 billion and expenditure of H$100 billion produce a balance of −H$10 billion: a deficit of H$10 billion. A one-year deficit is not the whole debt stock.</div>'),c('Automatic or deliberate?','<p><b>Automatic stabilisers</b> change taxes and benefits as economic activity changes, without a new policy decision. In recession, lower tax receipts and higher unemployment benefits cushion disposable income. <b>Discretionary fiscal policy</b> is a deliberate change, such as a new infrastructure programme.</p><div class="example">The budget can move towards deficit simply because incomes fall. This does not prove the government has announced a new stimulus.</div>'),c('HL: leakages limit the multiplier',HL+'<p>Initial spending becomes income, then some is spent again. Saving, taxation and imports leak from later rounds. Use the [[multiplier]] with stated marginal propensities, rather than assuming the full injection repeats forever.</p>'+F`k=\frac{1}{MPS+MPT+MPM}`+F`\Delta Y=k\Delta G`+'<div class="example">Marginal leakages of 0.5 imply k = 2. An extra H$10 million in purchases gives a modelled H$20 million equilibrium income rise when there is spare capacity and unchanged prices. A tax cut’s first consumption effect is smaller if households save some of it.</div>'),c('When the boost works best','<p>Fiscal expansion can reduce cyclical unemployment and targeted spending can improve services or capacity. Recognition, approval and construction lags may cause spending to arrive after recovery. Imports, debt concerns, interest costs and crowding out of private activity can weaken effects. Near capacity, more AD may mainly raise prices.</p><p><b>Crowding out</b> occurs when government activity reduces private spending, for example through higher borrowing costs or competition for scarce resources. It is less likely to dominate with idle resources and supportive monetary conditions.</p>'+tip)],
labs:[lab('Sort the budget response',['Automatic stabiliser','Expansionary discretionary','Contractionary discretionary'],[['Benefit spending rises under existing rules during recession',0],['A new law increases infrastructure purchases',1],['Parliament raises income tax rates to cool spending',2],['Income tax receipts fall because wages fall',0],['A new temporary tax cut raises disposable income',1],['Government cancels a spending programme to restrain demand',2]])],
worked:w('A stimulus with leakages',HL+tbl(['Item','Value'],[['New government purchases (million H$)','10'],['MPS','0.20'],['MPT','0.10'],['MPM','0.20']]),[['What is the marginal leakage?','0.20 + 0.10 + 0.20 = 0.50.'],['What is the multiplier?','1 / 0.50 = 2.'],['What income change does the simple model predict?','2 × H$10 million = H$20 million. This includes the initial purchase, not an additional H$20 million on top of it.'],['What could reduce the real effect?','Capacity constraints, imports beyond those assumed, changing saving behaviour or crowding out can reduce real output gains.']],'State the assumptions before turning a model result into a policy forecast.'),
quiz:[mc('Which directly raises G in expenditure GDP?',['A government purchase of a new bus','An unemployment benefit transfer','A tax rebate payment itself','A purchase of an existing financial asset'],0,'G counts purchases of current goods and services, rather than transfers.'),n('Calculate the budget balance, using revenue minus expenditure.'+tbl(['Item','Billion H$'],[['Revenue','90'],['Expenditure','100'],['Balance',A(-10,true)]]),-10,'90 − 100 = −10: a H$10 billion deficit.','billion H$'),tf('The budget deficit and public debt measure the same thing.',false,'A deficit is a flow over a period; debt is an outstanding stock.'),mc('Which is an automatic stabiliser?',['Tax receipts fall under existing rules when incomes fall','A new emergency spending law','A central-bank interest-rate cut','A newly announced income tax rate increase'],0,'No new policy decision is needed for receipts to fall with the tax base.'),n(HL+'Calculate the multiplier.'+tbl(['Marginal propensity','Value'],[['Save','0.2'],['Tax','0.1'],['Import','0.2'],['Multiplier',A(2,true)]]),2,'1 / (0.2 + 0.1 + 0.2) = 2.'),n(HL+'Calculate the predicted income increase.'+tbl(['Item','Value'],[['Spending injection (million H$)','15'],['Multiplier','2'],['Income increase (million H$)',A(30,true)]]),30,'15 × 2 = 30 in the stated simple multiplier model.','million H$'),mc('Expansion is most likely to raise real output strongly when…',['There is spare capacity and spending reaches domestic producers','All resources are already fully occupied','Every dollar is immediately spent on imports','All households save the entire transfer'],0,'Idle resources allow demand to translate into production rather than mainly inflation.'),tf('A larger deficit always proves a discretionary fiscal expansion has occurred.',false,'Automatic changes during recession can increase the deficit without a new stimulus decision.')],explain:'Text a friend why the government’s debt is like an accumulated balance, while this year’s deficit is a flow.'
},
{
id:'3.7',title:'Supply-side policies and policy packages',emoji:'🛠️',minutes:13,hl:false,
goal:'compare interventionist and market-based supply-side policies and judge policy combinations.',
hook:'<p>HarbourFest cannot find trained electricians and buses keep breaking down. Cheaper loans may increase bookings, but they cannot create qualified staff overnight. Harbourland needs to expand what its economy can produce.</p>',
cards:[c('Raise productive capacity','<p><b>Supply-side policies</b> aim to improve productive potential, efficiency and the functioning of markets. Successful policies can shift LRAS or Keynesian AS right, allowing higher sustainable output with less inflation pressure. Some also affect AD immediately.</p><div class="example">Building an efficient bus network raises G during construction and may later improve workers’ access to jobs. It is both a current demand injection and a potential capacity improvement.</div>'),c('Interventionist approaches','<p><b>Interventionist supply-side policy</b> uses public action such as education, training, healthcare, infrastructure and support for research. Human capital can raise productivity, and infrastructure can reduce firms’ costs. Targeted industrial support seeks to address coordination, information or financing problems.</p><div class="example">Apprenticeships help electricians qualify for festival work. Benefits depend on course quality and matching real vacancies; spending on buildings alone does not guarantee useful learning.</div>'),c('Market-based approaches','<p><b>Market-based supply-side policies</b> seek stronger incentives and competition through competition policy, privatisation, deregulation, labour-market reforms or changes to direct taxes. Greater competitive pressure may reduce costs and encourage innovation.</p><div class="example">Making it easier for safe new bus operators to enter can increase choice. Weakening essential safety rules would impose different costs; assess which regulation is changed.</div>'),c('Assess costs and distribution','<p>Training and infrastructure take time, require funding and carry opportunity costs. Privatisation without effective competition may create private market power. Lower benefits or weaker bargaining protection may strengthen some work incentives but increase insecurity and inequality. Tax cuts do not guarantee productive investment.</p><div class="example">A lower company tax rate helps the festival supplier only if demand, skills and expected returns make investment attractive. Publicly funded training may be more relevant where skills are the binding constraint.</div>'),c('Choose a coherent package','<p>Combine policies around the diagnosed problem. Demand support can use current idle resources while supply measures develop future capacity. Stable institutions, credible implementation, environmental standards and distributional support can improve results. No single policy meets every objective in every context.</p><div class="tip">Recommend: identify the binding constraint, compare feasible policies and justify the best combination, including timing, financing and affected groups.</div>')],
labs:[lab('Build the policy package',['Interventionist supply-side','Market-based supply-side','Primarily demand management'],[['Public vocational training linked to vacancies',0],['Competition rules prevent cartel agreements',1],['A short-term policy interest-rate cut',2],['A reliable public transport infrastructure project',0],['Simpler entry rules for new firms while retaining safety standards',1],['A temporary general household cash transfer',2]])],
worked:w('Fix the electrician shortage','<p>Harbourland has vacancies for qualified electricians but unemployed workers lack certification. Government funds are limited.</p>',[['What is the binding constraint?','A skills mismatch, so the main problem is structural rather than just insufficient demand.'],['Which intervention fits?','Targeted training with employers, recognised qualifications and support for trainees’ travel or childcare.'],['What market reform could complement it?','Improve qualification recognition and job information, while retaining necessary safety standards.'],['What limits should shape the recommendation?','Training takes time and costs resources. Evaluate completion, job placement and additionality rather than simply counting enrolments.']],'A useful policy package fits the cause and includes a way to assess results.'),
quiz:[mc('Successful supply-side policy primarily aims to increase…',['Productive potential and efficiency','Only the average price level','Only government debt','The need for imports in every industry'],0,'It seeks to improve the economy’s ability to produce sustainably.'),mc('Which is interventionist supply-side policy?',['Publicly supported vocational training','A short-term policy-rate cut','A purely temporary sales promotion','Only a transfer to existing asset owners'],0,'Training can build human capital and reduce structural mismatches.'),mc('Which is market-based supply-side policy?',['Removing unnecessary barriers to market entry','Increasing unemployment benefits during a recession under existing rules','A central-bank asset purchase','A temporary rise in government consumption alone'],0,'Entry reform can strengthen competition and incentives.'),tf('An infrastructure programme can affect both AD now and AS later.',true,'Construction adds spending; useful completed infrastructure can raise capacity.'),mc('What is a risk of privatisation without competition?',['Private market power may replace public monopoly','Every price must fall to zero','All regulations become unnecessary','The government automatically loses every tax receipt'],0,'Ownership change alone does not ensure competitive discipline.'),mc('Which is the strongest response to a documented skills shortage?',['Training tied to vacancies with completion and placement checks','An untargeted claim that all taxes should vanish','More consumer demand with no skills measures','Changing statistical definitions of employment'],0,'A targeted response addresses the mismatch and checks actual outcomes.'),tf('Lower direct tax rates guarantee that firms invest more.',false,'Expected demand, finance, skills and confidence also affect investment.'),mc('For a recommendation, which evidence matters most?',['The binding constraint, timing, costs and affected groups','Only whether a policy has a popular name','Only a promise of immediate gains','Whether one objective can be ignored'],0,'Evaluation compares feasible outcomes in the stated context.')],explain:'Text a friend why cheaper loans cannot instantly fix a shortage of trained electricians, and propose a useful policy pair.'
}
];
// Additional HL quantitative practice belongs alongside the shared conceptual lesson.
const byId=id=>sections.find(s=>s.id===id);
byId('3.2').cards[2].html+=asDiagram+'<p>Draw each model on its own axes in an exam. Add a downward AD curve: it can intersect Keynesian AS below full employment, whereas new classical long-run equilibrium is at potential after price and wage adjustment.</p>';
byId('3.2').labs.push({type:'equilibrium',title:'Shift AD and SRAS',mode:'macro',challenge:'Compare spending and cost shocks.'});
byId('3.3b').cards[4].html+=phillipsDiagram+'<p>To draw a demand-led short-run trade-off, move along one SRPC. To show changed expectations, shift SRPC. Do not show a permanent movement along a downward-sloping long-run curve.</p>';
byId('3.3a').cards[3].html=byId('3.3a').cards[3].html.replace('including frictional and structural components','including frictional, structural and seasonal components');
byId('3.3b').cards.push(c('HL: construct a weighted price index',HL+'<p>Use expenditure shares as weights. Multiply each category price relative by its weight and add. Keep weights in decimal form, or divide percentage-weight totals by 100.</p>'+F`\text{Weighted index}=\sum_i w_i I_i`+tbl(['Category','Weight','Price index'],[['Food','0.6','120'],['Transport','0.4','110']])+'<div class="example">0.6 × 120 + 0.4 × 110 = 116. With the base index 100, the weighted basket has risen 16%. A change in one high-weight category matters more than the same change in a low-weight category.</div>'));
byId('3.3b').quiz.push(n(HL+'Calculate the weighted price index.'+tbl(['Category','Weight','Index'],[['Food','0.6','120'],['Transport','0.4','110'],['Weighted index','',A(116,true)]]),116,'0.6 × 120 + 0.4 × 110 = 116.'));
byId('3.4').cards.push(c('HL: build a Lorenz curve and calculate indirect tax',HL+'<p>Convert income shares into cumulative shares before plotting. Five equally sized population groups have cumulative population shares of 20%, 40%, 60%, 80% and 100%.</p>'+tbl(['Quintile','Income share (%)','Cumulative income (%)'],[['Poorest','5','5'],['Second','10','15'],['Third','15','30'],['Fourth','25','55'],['Richest','45','100']])+'<p>Plot (0,0), (20,5), (40,15), (60,30), (80,55), (100,100), and join the points. For an indirect tax quoted as a proportion of the pre-tax price, multiply the pre-tax price by the rate. If H$120 already includes a 20% tax on the pre-tax price, the tax is H$20, not H$24.</p>'+F`\text{Tax included in price}=\frac{t}{1+t}\times\text{tax-inclusive price}`+'<p>Tax and poverty comparisons also need reliable household data, appropriate living-cost assumptions and a view of fairness. Equal incomes are not necessarily equitable when needs differ. Universal basic income reduces eligibility gaps but costs more than narrowly targeted support; anti-discrimination measures and accessible services address unequal opportunity.</p>'));
byId('3.4').cards[5].html+='<svg viewBox="0 0 420 285" role="img" aria-label="Lorenz curve from the quintile data: cumulative income shares are 5, 15, 30, 55 and 100 percent for cumulative population shares of 20, 40, 60, 80 and 100 percent" style="width:100%;height:auto;background:var(--card);color:var(--text);border-radius:12px"><path d="M55 30V230H355" fill="none" stroke="var(--text)" stroke-width="2"/><path d="M55 230L355 30" fill="none" stroke="var(--chart-3)" stroke-width="2" stroke-dasharray="5 4"/><path d="M55 230L115 220L175 200L235 170L295 120L355 30" fill="none" stroke="var(--chart-1)" stroke-width="3"/><text x="8" y="18" font-size="12" fill="var(--text)">Cumulative income (%)</text><text x="160" y="273" font-size="12" fill="var(--text)">Cumulative population (%)</text><text x="39" y="244" font-size="11" fill="var(--text)">0</text><text x="346" y="244" font-size="11" fill="var(--text)">100</text><text x="27" y="34" font-size="11" fill="var(--text)">100</text><text x="88" y="112" font-size="12" fill="var(--muted)">Equality line</text><text x="235" y="196" font-size="12" fill="var(--chart-1)">Lorenz curve</text></svg>';
byId('3.4').quiz.push(n(HL+'Find tax contained in the price. The rate applies to the pre-tax price.'+tbl(['Item','Value'],[['Tax-inclusive price (H$)','120'],['Tax rate','20%'],['Tax amount (H$)',A(20,true)]]),20,'Pre-tax price = 120 / 1.2 = 100; tax = 120 − 100 = 20.','H$'));
byId('3.5').cards.push(c('HL tools, bank deposits and real rates',HL+'<p>When a commercial bank makes a loan it normally creates a matching deposit: lending creates money, while repayment of the principal reverses that deposit creation. Banks face capital, liquidity, credit risk, profitability and demand constraints, so reserves do not generate unlimited loans mechanically. Central banks can influence conditions through open-market operations, reserve requirements where used, and the rate charged for central-bank lending.</p><p>Buying securities in open-market operations adds reserves and can ease monetary conditions. Raising minimum reserve requirements can constrain lending where these rules bind; raising the central-bank lending rate tends to tighten conditions.</p><p><b>Real interest rates</b> adjust nominal rates for inflation. For both SL and HL, an approximate real rate is nominal interest minus inflation; use expected inflation when judging a forward-looking borrowing decision.</p>'+F`r\approx i-\pi`+'<div class="example">A 6% nominal rate with 4% inflation means an approximate real rate of 2%. The exact rate is (1.06 / 1.04 − 1) × 100, about 1.92%.</div>'));
byId('3.5').quiz.push(n('Calculate the approximate real interest rate.'+tbl(['Item','Rate (%)'],[['Nominal interest','6'],['Inflation','4'],['Approximate real interest',A(2,true)]]),2,'Approximate real interest = 6 − 4 = 2%.','%'),tf(HL+'A commercial-bank loan normally creates a matching deposit.',true,'Loan creation adds a bank asset and a matching deposit liability; lending remains constrained by risk, capital, liquidity and demand.'));
byId('3.6').cards[2].html=HL+byId('3.6').cards[2].html;
byId('3.6').cards[3].html+='<p>In a simple economy with only consumption and saving as responses to extra income, the equivalent formula is k = 1 / (1 − MPC). For MPC = 0.75, k = 4. In the open-economy version use all marginal leakages consistently.</p>'+F`k=\frac{1}{1-MPC}`;
byId('3.6').cards[4].html=byId('3.6').cards[4].html.replace('<p><b>Crowding out</b>',HL+'<p><b>Crowding out</b>');
byId('3.6').quiz[3].q=HL+byId('3.6').quiz[3].q;
byId('3.6').quiz[7].q=HL+byId('3.6').quiz[7].q;
byId('3.6').cards[0].html+='<p>Revenue comes from direct and indirect taxes, state-enterprise sales and some asset sales. Current expenditure funds ongoing services; capital expenditure funds long-lived assets; transfer payments redistribute income without directly purchasing current output. Fiscal choices can also affect distribution and external balance, not only demand.</p>';
sections.splice(5,0,{
id:'3.3c',title:'Government debt and sustainability',emoji:'📚',minutes:10,hl:true,
goal:'calculate debt relative to GDP and judge the sustainability of public borrowing.',
hook:'<p>Harbourland borrows to repair flood-damaged transport. A headline says debt is at a record level, but the economy has also grown. You must judge what the debt costs and whether the spending strengthens future income.</p>',
cards:[c('HL: stock versus flow',HL+'<p><b>Government debt</b> is an outstanding stock. A budget deficit is new net borrowing over a period. Debt usually rises when deficits are financed by borrowing, though asset transactions, exchange-rate changes and other adjustments can alter the recorded stock.</p><div class="example">Starting debt of H$300 billion plus a H$10 billion borrowing-financed deficit gives H$310 billion, assuming no other changes.</div>'),c('HL: scale it against national income',HL+'<p>The <b>debt-to-GDP ratio</b> compares outstanding debt with annual nominal GDP. It helps assess the scale of liabilities relative to the income base supporting taxes. A rising nominal debt can coincide with a falling ratio if nominal GDP grows faster.</p>'+F`\text{Debt-to-GDP}=\frac{\text{government debt}}{\text{nominal GDP}}\times100`+'<div class="example">Debt of 300 and GDP of 500 imply 60%. Debt rising to 315 while GDP rises to 550 lowers the ratio to about 57.27%.</div>'),c('HL: affordability and risk',HL+'<p><b>Debt servicing</b> means interest and scheduled repayments. Higher interest costs can crowd out public services or require higher future taxes. Credit ratings, maturity, interest rates, the currency of borrowing, investor confidence and expected growth influence refinancing risk. Foreign-currency debt becomes harder to service if the domestic currency depreciates.</p><p>There is no universal debt ratio that separates safe from unsafe borrowing. Productive investment can support future income, while persistent waste weakens the tax base. Austerity can reduce borrowing but may deepen a recession and lower GDP.</p>'+tip)],
labs:[lab('Assess debt information',['Stock','Flow','Sustainability factor'],[['Outstanding public debt on 31 December',0],['This year’s budget deficit',1],['Annual interest expenditure',1],['Currency denomination of government borrowing',2],['Expected growth of the future tax base',2],['Remaining maturity of bonds',2]])],
worked:w('Debt rises, ratio falls',tbl(['Item','Initial','Final'],[['Debt (billion H$)','300','315'],['Nominal GDP (billion H$)','500','550']]),[['What is the initial ratio?','300 / 500 × 100 = 60%.'],['What is the final ratio?','315 / 550 × 100 ≈ 57.27%. Nominal debt rose, but the ratio fell.'],['Does that prove borrowing is sustainable?','No. Check interest costs, maturity, currency, expected future budgets and the quality of funded spending.']],'Use a ratio and a financing assessment together.'),
quiz:[n('Calculate the debt-to-GDP ratio.'+tbl(['Item','Billion H$'],[['Debt','300'],['Nominal GDP','500'],['Debt-to-GDP (%)',A(60,true)]]),60,'300 / 500 × 100 = 60%.','%'),n('Calculate closing debt, assuming the deficit is entirely borrowed and no other stock changes occur.'+tbl(['Item','Billion H$'],[['Opening debt','300'],['Deficit','10'],['Closing debt',A(310,true)]]),310,'300 + 10 = 310.','billion H$'),mc('Debt servicing primarily concerns…',['Interest and scheduled repayments','Only new festival ticket sales','Every household’s private debt','Only the inflation index'],0,'Servicing obligations require resources from the government budget.'),tf('A rise in nominal government debt always raises the debt-to-GDP ratio.',false,'The ratio can fall if nominal GDP grows faster.'),mc('Why does foreign-currency debt create exchange-rate risk?',['Domestic depreciation raises its domestic-currency servicing cost','Domestic depreciation erases the debt','It guarantees zero interest','Foreign lenders cannot request repayment'],0,'More local currency is needed to obtain the currency of repayment.'),mc('Which most supports future debt sustainability?',['Productive investment that strengthens the future tax base','Spending with no benefits and permanent high servicing costs','Ignoring bond maturities','Assuming one universal safe debt ratio'],0,'Sustainable income and revenues help meet future obligations.'),tf('Fiscal cuts can sometimes increase the debt-to-GDP ratio initially.',true,'If cuts sharply reduce GDP, the denominator can fall enough to offset debt restraint.'),mc('Which judgement is most defensible?',['Assess debt ratio, interest costs, maturity, currency and growth together','Any record nominal debt is automatically unsustainable','All public borrowing pays for itself','Debt ratios are the only relevant evidence'],0,'Sustainability depends on the financing context and future capacity to pay.')],
explain:'Text a friend how Harbourland’s debt can rise while its debt-to-GDP ratio falls.'
});
sections.sort((a,b)=>a.id.localeCompare(b.id,'en',{numeric:true}));
for(const s of sections) s.quiz.forEach((q,i)=>q.id=`${s.id}-${i+1}`);
export const unit3={id:'3',title:'Macroeconomics',emoji:'🏦',blurb:'Help fictional Harbourland balance growth, jobs, prices and fairness while HarbourFest navigates the economic cycle.',sections,formulas:[
{group:'3.1 National income',items:[{name:'Expenditure GDP',f:M`GDP=C+I+G+(X-M)`},{name:'GNI',f:M`GNI=GDP+\text{net primary income from abroad}`},{name:'Real income',f:M`\text{Real income}=\frac{\text{nominal income}}{\text{price deflator}}\times100`},{name:'Income per person',f:M`\text{Per capita income}=\frac{\text{income}}{\text{population}}`}]},
{group:'3.3 Objectives',items:[{name:'Real growth',f:M`g=\frac{Y_1-Y_0}{Y_0}\times100`},{name:'Unemployment',f:M`u=\frac{\text{unemployed}}{\text{labour force}}\times100`},{name:'CPI',f:M`CPI=\frac{\text{current basket cost}}{\text{base basket cost}}\times100`},{name:'Inflation',f:M`\pi=\frac{CPI_1-CPI_0}{CPI_0}\times100`},{name:'Weighted index',f:M`I=\sum_i w_i I_i`,hl:true,note:'Use decimal expenditure weights summing to one.'},{name:'Debt-to-GDP ratio',f:M`\text{Debt ratio}=\frac{\text{debt}}{\text{nominal GDP}}\times100`,hl:true}]},
{group:'3.4 Distribution',items:[{name:'Gini coefficient',f:M`G=\frac{A}{A+B}`,note:'A is the area between equality line and Lorenz curve; A+B is the total area under the equality line.'},{name:'Average tax rate',f:M`ATR=\frac{\text{tax}}{\text{income}}\times100`,hl:true},{name:'Marginal tax rate',f:M`MTR=\frac{\Delta\text{tax}}{\Delta\text{income}}\times100`,hl:true}]},
{group:'3.5 Monetary policy',items:[{name:'Approximate real interest',f:M`r\approx i-\pi`,note:'Nominal interest minus inflation; use expected inflation for a forward-looking real rate.'}]},
{group:'3.6 Fiscal policy',items:[{name:'Budget balance',f:M`\text{Balance}=\text{revenue}-\text{expenditure}`},{name:'Simple consumption multiplier',f:M`k=\frac{1}{1-MPC}`,hl:true,note:'Simple model in which extra income is consumed or saved.'},{name:'Open-economy multiplier',f:M`k=\frac{1}{MPS+MPT+MPM}`,hl:true,note:'Assumes spare capacity, fixed price level and unchanged marginal propensities.'},{name:'Multiplier income change',f:M`\Delta Y=k\Delta J`,hl:true}]}
]};
